## Git hooks

Repo-local git hooks are configured via devenv and call `devenv tasks run` directly — no separate task runner needed:

- `pre-commit`: `keating:check-version`
- `pre-push`: `keating:test` + `keating:test-web`
# Standard.site Blog on the Keating PDS

Keating's public blog is read from `site.standard.publication` and
`site.standard.document` records in one AT Protocol repository. The web server
resolves the configured handle to its DID, follows the DID document to the
account's current PDS, and reads the records there. Moving the account to a
Tranquil PDS therefore does not change article URLs or require a client rebuild.

## Record shape

- Publication: `site.standard.publication`, record key `self`, canonical URL
  `https://keating.help`.
- Documents: `site.standard.document`, with stable slug record keys and paths at
  `/blog/<slug>`.
- Rich body: `at.markpub.markdown` using GFM.
- Portable fallback: `textContent` contains a formatting-free representation.

Article HTML includes `<link rel="site.standard.document" href="at://...">`.
The publication is verified at:

```text
https://keating.help/.well-known/site.standard.publication
```

## Prepare the historical posts

The publisher is dry-run by default. It renders the retired JSX archive to GFM
and writes the exact publication/document payloads under `.keating/outputs/`:

```bash
cd web
bun scripts/publish-standard-site-blog.ts
```

Inspect `.keating/outputs/standard-site-blog.json` before writing anything to a
PDS. To prepare or publish one post, pass its generated record key:

```bash
bun scripts/publish-standard-site-blog.ts --only=v2-10-0-example
```

## Publish to Tranquil

Create the Keating account and an app password on the Tranquil PDS. Keep the
password outside the repository and shell history. Have the deployment secret
store inject these three variables:

```text
KEATING_BLOG_PDS_URL
KEATING_BLOG_IDENTIFIER
KEATING_BLOG_APP_PASSWORD
```

Then publish without placing the password in the command:

```bash
cd web
bun scripts/publish-standard-site-blog.ts --write
```

`--write` uses `com.atproto.server.createSession`, then upserts records with
`com.atproto.repo.putRecord`. Stable record keys make repeat runs idempotent.
The script prints the durable publication AT-URI after a successful run.

## Runtime configuration

Configure the Nitro deployment with:

```text
KEATING_BLOG_ATPROTO_REPO=blog.keating.help
KEATING_BLOG_PUBLICATION_URI=at://did:plc:.../site.standard.publication/self
KEATING_BLOG_CANONICAL_URL=https://keating.help
```

`KEATING_BLOG_ATPROTO_REPO` may be the handle or DID. Prefer the handle so the
status UI remains readable; records and verification always use the durable
DID-based URI.

Optional settings:

```text
KEATING_BLOG_PDS_URL=https://pds.example
KEATING_BLOG_HANDLE_RESOLVER=https://public.api.bsky.app
KEATING_BLOG_PLC_DIRECTORY=https://plc.directory
```

`KEATING_BLOG_PDS_URL` is a deployment override for local or staged Tranquil
instances. In normal production use, omit it so Keating follows the PDS endpoint
in the DID document and survives account migration automatically.

No PDS access token or app password is sent to the browser. Blog reads use the
public repository APIs through Keating's same-origin `/api/blog` route.
import b4a from "b4a";
import type Hyperbee from "hyperbee";
import type { CorestoreLike, PeerStats } from "./types.js";
import { joinSwarm, type SwarmFactory, type SwarmHandle } from "./swarm.js";

interface CourseCore {
	key: Uint8Array;
	discoveryKey: Uint8Array;
	length: number;
	ready(): Promise<void>;
}

export interface CourseFeedConfig {
	storageDir: string;
	courseId?: string;
	publicKey?: string;
	joinSwarm?: SwarmFactory;
}

/**
 * Server-authoritative Pear feed for the share-safe projection of one course.
 * The gateway is the only writer. Installed Pear clients open the public key as
 * readers, so no signing key ever leaves the server and no multiwriter forks
 * are possible.
 */
export class CourseFeed {
	private coreStore: CorestoreLike | null = null;
	private core: CourseCore | null = null;
	private bee: Hyperbee | null = null;
	private swarm: SwarmHandle | null = null;
	private writable = false;

	private constructor() {}

	static async openWriter(config: CourseFeedConfig): Promise<CourseFeed> {
		if (!config.courseId) throw new Error("CourseFeed.openWriter requires courseId.");
		return CourseFeed.open(config, { name: `keating-course-${config.courseId}` }, true);
	}

	static async openReader(config: CourseFeedConfig): Promise<CourseFeed> {
		if (!config.publicKey || !/^[0-9a-f]{64}$/i.test(config.publicKey)) {
			throw new Error("CourseFeed.openReader requires a 32-byte hex public key.");
		}
		return CourseFeed.open(config, { key: b4a.from(config.publicKey, "hex") }, false);
	}

	private static async open(
		config: CourseFeedConfig,
		coreOptions: { name: string } | { key: Uint8Array },
		writable: boolean,
	): Promise<CourseFeed> {
		const { default: Corestore } = await import("corestore");
		const store = new Corestore(config.storageDir) as unknown as CorestoreLike;
		await store.ready();
		const core = store.get(coreOptions) as unknown as CourseCore;
		await core.ready();
		const { default: HyperbeeConstructor } = await import("hyperbee");
		const bee = new HyperbeeConstructor(core as never, {
			keyEncoding: "utf-8",
			valueEncoding: "json",
		});
		await bee.ready();

		const feed = new CourseFeed();
		feed.coreStore = store;
		feed.core = core;
		feed.bee = bee;
		feed.writable = writable;
		feed.swarm = await (config.joinSwarm ?? joinSwarm)(core.discoveryKey, (socket) => {
			store.replicate(socket);
		});
		await feed.swarm.ready();
		return feed;
	}

	get publicKey(): string {
		if (!this.core) throw new Error("CourseFeed is not open.");
		return b4a.toString(this.core.key, "hex");
	}

	stats(): PeerStats {
		if (!this.core) throw new Error("CourseFeed is not open.");
		const peers = this.swarm?.peerCount ?? 0;
		return {
			topicHex: b4a.toString(this.core.discoveryKey, "hex"),
			peers,
			writableLength: this.core.length,
			connected: peers > 0,
		};
	}

	async setSnapshot(value: unknown): Promise<void> {
		if (!this.writable) throw new Error("CourseFeed reader cannot write.");
		if (!this.bee) throw new Error("CourseFeed is not open.");
		await this.bee.put("course", value);
	}

	async getSnapshot<T = unknown>(): Promise<T | null> {
		if (!this.bee) throw new Error("CourseFeed is not open.");
		await (this.bee.core as unknown as { update(): Promise<void> }).update();
		const entry = await this.bee.get("course");
		return entry?.value as T | null ?? null;
	}

	async close(): Promise<void> {
		await this.swarm?.destroy();
		this.swarm = null;
		await this.bee?.close();
		this.bee = null;
		await this.coreStore?.close();
		this.coreStore = null;
		this.core = null;
	}
}
import type { Api, Model } from "@earendil-works/pi-ai/compat";

export const LONG_CONTEXT_THRESHOLD = 256_000;

export const CHAT_CAPABILITY_FILTERS = [
	{ value: "thinking", label: "Thinking" },
	{ value: "vision", label: "Vision" },
	{ value: "long-context", label: "Long context" },
] as const;

export type ChatCapabilityFilter = (typeof CHAT_CAPABILITY_FILTERS)[number]["value"];

export function modelHasCapability(model: Model<Api>, capability: ChatCapabilityFilter): boolean {
	switch (capability) {
		case "thinking":
			return model.reasoning === true;
		case "vision":
			return model.input.includes("image");
		case "long-context":
			return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
		default:
			return true;
	}
}

export function modelHasCapabilities(model: Model<Api>, capabilities: readonly ChatCapabilityFilter[]): boolean {
	return capabilities.every((capability) => modelHasCapability(model, capability));
}

export function modelCapabilityBadges(model: Model<Api>): string[] {
	return [
		model.input.includes("image") ? "Vision" : "",
		model.reasoning ? "Thinking" : "",
		model.contextWindow >= LONG_CONTEXT_THRESHOLD ? "Long context" : "",
	].filter(Boolean);
}
import { useCallback, useSyncExternalStore } from "react";

export type PersistedSettingsSubscriber = (onStoreChange: () => void) => () => void;

/**
 * React adapter for the small localStorage-backed stores used by Keating.
 * The store remains the source of truth; React only subscribes to snapshots.
 */
export function usePersistedSettings<T extends object>(
	load: () => T,
	save: (next: T) => void,
	subscribe: PersistedSettingsSubscriber,
): [T, (patch: Partial<T>) => void] {
	const snapshot = useSyncExternalStore(subscribe, load, load);
	const patch = useCallback((next: Partial<T>) => {
		save({ ...load(), ...next });
	}, [load, save]);

	return [snapshot, patch];
}

