import type { Course, CourseNetworkInfo } from "../../src/courses/contracts";

interface GatewayEntry {
	feed: CourseFeed;
	lastRevision: number;
}

interface CoursePearGlobals {
	__keatingCoursePearFeeds?: Map<string, Promise<GatewayEntry>>;
}

const globals = globalThis as typeof globalThis & CoursePearGlobals;
const feeds = globals.__keatingCoursePearFeeds ??= new Map<string, Promise<GatewayEntry>>();

function enabled(): boolean {
	const value = process.env.KEATING_COURSES_PEAR_ENABLED?.trim().toLowerCase();
	return value === "1" || value === "true";
}

function storageBase(): string {
	return process.env.KEATING_COURSES_PEAR_STORAGE_DIR?.trim() || ".data/keating-course-pear";
}

/** Never place private learner work or consent state on the read-only Pear feed. */
export function projectCourseForPear(course: Course): Course {
	const projected = structuredClone(course);
	projected.submissions = projected.submissions.filter((submission) => submission.sharedWithPeers);
	projected.members = projected.members.map((member) => ({
		accountId: member.accountId,
		displayName: member.displayName,
		role: member.role,
		teacherAccess: "private",
		// Preserve the Course schema using a course-level timestamp, never account activity.
		joinedAt: projected.createdAt,
		progress: {
			completedLessonIds: [],
			lastActiveAt: projected.createdAt,
		},
	}));
	projected.activity = [];
	return projected;
}

async function openFeed(course: Course): Promise<GatewayEntry> {
	const { CourseFeed } = await import("../../../packages/p2p-core/src/course-feed.js");
	const feed = await CourseFeed.openWriter({
		courseId: course.id,
		storageDir: `${storageBase()}/${course.id}`,
	});
	await feed.setSnapshot(projectCourseForPear(course));
	return { feed, lastRevision: course.revision };
}

function offline(): CourseNetworkInfo {
	return { mode: "pear-gateway", status: "offline", peerCount: 0 };
}

export async function mirrorCourseOnPear(course: Course): Promise<CourseNetworkInfo> {
	if (!enabled()) return offline();
	try {
		let entryPromise = feeds.get(course.id);
		if (!entryPromise) {
			entryPromise = openFeed(course);
			feeds.set(course.id, entryPromise);
		}
		const entry = await entryPromise;
		if (entry.lastRevision < course.revision) {
			await entry.feed.setSnapshot(projectCourseForPear(course));
			entry.lastRevision = course.revision;
		}
		const stats = entry.feed.stats();
		return {
			mode: "pear-gateway",
			status: "connected",
			peerCount: stats.peers,
			publicKey: entry.feed.publicKey,
		};
	} catch (error) {
		feeds.delete(course.id);
		console.warn("Keating course Pear gateway is unavailable:", error instanceof Error ? error.message : "unknown error");
		return { mode: "pear-gateway", status: "reconnecting", peerCount: 0 };
	}
}
import type { Peer } from "crossws";
import type { CourseRealtimeMessage } from "../../src/courses/contracts";

interface CourseRealtimePeer {
	peer: Peer;
	accountId: string;
}

interface CourseRealtimeGlobals {
	__keatingCoursePeers?: Map<string, Map<string, CourseRealtimePeer>>;
}

const globals = globalThis as typeof globalThis & CourseRealtimeGlobals;
const coursePeers = globals.__keatingCoursePeers ??= new Map<string, Map<string, CourseRealtimePeer>>();

function send(peer: Peer, message: CourseRealtimeMessage): void {
	peer.send(JSON.stringify(message));
}

function peersFor(courseId: string): Map<string, CourseRealtimePeer> {
	let peers = coursePeers.get(courseId);
	if (!peers) {
		peers = new Map();
		coursePeers.set(courseId, peers);
	}
	return peers;
}

function broadcastPresence(courseId: string): void {
	const peers = coursePeers.get(courseId);
	if (!peers) return;
	const accountIds = [...new Set([...peers.values()].map((connection) => connection.accountId))];
	const message: CourseRealtimeMessage = { type: "presence", courseId, accountIds };
	for (const connection of peers.values()) send(connection.peer, message);
}

export function connectCoursePeer(courseId: string, accountId: string, peer: Peer): void {
	peersFor(courseId).set(peer.id, { peer, accountId });
	broadcastPresence(courseId);
}

export function disconnectCoursePeer(courseId: string, peer: Peer): void {
	const peers = coursePeers.get(courseId);
	if (!peers) return;
	peers.delete(peer.id);
	if (peers.size === 0) coursePeers.delete(courseId);
	else broadcastPresence(courseId);
}

export function broadcastCourseUpdated(courseId: string, revision: number): void {
	const peers = coursePeers.get(courseId);
	if (!peers) return;
	const message: CourseRealtimeMessage = { type: "course.updated", courseId, revision };
	for (const connection of peers.values()) send(connection.peer, message);
}
