			<div className={css({ display: "flex", minW: 0, alignItems: "center", gap: "0.75rem" })}><Link to="/courses" aria-label="Back to courses" className={css({ display: "grid", h: "2rem", w: "2rem", flexShrink: 0, placeItems: "center", color: "inherit", _hover: { bg: "var(--course-wash, #ddebdd)" } })}><ArrowLeft size={18} /></Link><div className={css({ minW: 0 })}><p className={s.sectionLabel}>Course desk</p><h1 className={css({ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontFamily: "Georgia, serif", fontSize: "1.15rem", fontWeight: 700 })}>{course.title}</h1></div></div>
			<div className={css({ display: "flex", alignItems: "center", gap: "0.6rem" })}><div className={s.mode}><button type="button" className={s.modeButton} style={mode === "desk" ? { background: "var(--ink)", color: "var(--paper)" } : undefined} onClick={() => setMode("desk")}>Desk</button><button type="button" className={s.modeButton} style={mode === "room" ? { background: "var(--ink)", color: "var(--paper)" } : undefined} onClick={() => setMode("room")}>Room</button></div>{snapshot.permissions.canInvite && <button type="button" className={cx(s.button, s.primaryButton)} onClick={() => setInviteOpen(true)}><Share2 size={15} /><span className={css({ display: { base: "none", sm: "inline" } })}>Invite</span></button>}</div>
		</div></header>

		{error && <div role="alert" className={css({ position: "sticky", top: "58px", zIndex: 30, display: "flex", alignItems: "center", justifyContent: "space-between", gap: "1rem", borderBottom: "1px solid var(--destructive)", bg: "#f8e4de", px: "1rem", py: "0.6rem", color: "#7d2b1d" })}><span>{error}</span><button type="button" onClick={() => setError("")} aria-label="Dismiss"><X size={16} /></button></div>}
		{viewer.teacherAccess === "requested" && <div className={css({ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "center", gap: "0.75rem", borderBottom: "2px solid var(--ink)", bg: "#fff0d4", px: "1rem", py: "0.75rem", fontSize: "0.82rem" })}><strong>Your teacher requested full access to current and future course work.</strong><button type="button" className={cx(s.button, s.primaryButton)} onClick={() => void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "teacher-access.respond", approve: true }, "access")}>Approve once</button><button type="button" className={s.button} onClick={() => void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "teacher-access.respond", approve: false }, "access")}>Keep private</button></div>}

		<div className={s.grid}>
			<aside className={s.left}>
				<p className={s.sectionLabel}>Course outline</p>
				<div className={css({ mt: "0.75rem", display: "grid", gap: "1rem" })}>{course.modules.map((module) => <section key={module.id}><h2 className={css({ mb: "0.35rem", fontSize: "0.75rem", fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.04em" })}>{module.title}</h2><div className={css({ display: "grid", gap: "0.25rem" })}>{module.lessons.map((lesson, index) => { const done = viewer.progress.completedLessonIds.includes(lesson.id); return <button key={lesson.id} type="button" onClick={() => { setActiveLessonId(lesson.id); setMode("desk"); }} className={css({ display: "grid", gridTemplateColumns: "1.4rem minmax(0, 1fr)", gap: "0.45rem", borderLeft: "3px solid transparent", px: "0.4rem", py: "0.5rem", textAlign: "left", _hover: { bg: "var(--card)" } })} style={activeLesson.id === lesson.id ? { background: "var(--card)", borderLeftColor: "var(--course-green)" } : undefined}><span className={css({ display: "grid", h: "1.25rem", w: "1.25rem", placeItems: "center", borderRadius: "50%", bg: done ? "var(--course-green)" : "transparent", color: done ? "white" : "var(--ink-soft)" })}>{done ? <Check size={12} /> : index + 1}</span><span className={css({ fontSize: "0.78rem", lineHeight: 1.35 })}>{lesson.title}</span></button>; })}</div></section>)}</div>
				<div className={css({ mt: "1.25rem", borderTop: "1px solid var(--ink)", pt: "1rem" })}><p className={s.sectionLabel}>Course material</p><div className={css({ mt: "0.6rem", display: "grid", gap: "0.4rem", fontSize: "0.76rem" })}>{course.materials.length ? course.materials.map((material) => <a key={material.id} href={material.url} target="_blank" rel="noreferrer" className={css({ display: "flex", alignItems: "center", gap: "0.4rem", color: "inherit" })}><FileText size={14} /> {material.title}</a>) : <span className={css({ color: "var(--ink-soft)" })}>No sources yet</span>}</div></div>
				<div className={css({ mt: "1rem", display: "flex", alignItems: "center", justifyContent: "space-between", borderTop: "1px solid var(--ink)", pt: "1rem" })}><span className={css({ display: "inline-flex", alignItems: "center", gap: "0.4rem", fontSize: "0.78rem", fontWeight: 700 })}><Layers3 size={15} /> Anki deck</span><span className={css({ fontFamily: "var(--mono-display)", fontSize: "0.7rem" })}>{course.cards.length} cards</span></div>
			</aside>

			<main className={s.center}>{mode === "desk" ? <DeskView lesson={activeLesson} moduleTitle={activeModule?.title ?? "Course"} completed={completed} noteText={noteText} setNoteText={setNoteText} sharedNoteVersion={sharedNote?.version ?? 0} answer={answer} setAnswer={setAnswer} shareAnswer={shareAnswer} setShareAnswer={setShareAnswer} saving={saving} onComplete={() => void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "lesson.complete", lessonId: activeLesson.id, completed: !completed }, "complete")} onSaveNote={() => void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "shared-note.update", noteId: sharedNote?.id ?? `note_${activeLesson.id}`, lessonId: activeLesson.id, title: `${activeLesson.title} notes`, text: noteText, baseVersion: sharedNote?.version ?? 0 }, "note")} onSaveAnswer={() => activeLesson.exercise && void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "submission.save", submissionId: ownSubmission?.id ?? `submission_${crypto.randomUUID().replaceAll("-", "")}`, lessonId: activeLesson.id, exerciseId: activeLesson.exercise.id, answer, sharedWithPeers: shareAnswer }, "answer")} /> : <RoomView snapshot={snapshot} activeLesson={activeLesson} online={online} comment={comment} setComment={setComment} saving={saving} onComment={() => { if (!comment.trim()) return; void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "comment.add", commentId: `comment_${crypto.randomUUID().replaceAll("-", "")}`, lessonId: activeLesson.id, body: comment.trim() }, "comment").then(() => setComment("")); }} onReview={(submissionId, feedback) => mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "submission.review", submissionId, status: "reviewed", feedback }, "review")} />}</main>

			<aside className={s.right}>
				<div className={css({ display: "flex", alignItems: "center", justifyContent: "space-between" })}><p className={s.sectionLabel}>Live room</p><span className={css({ display: "inline-flex", alignItems: "center", gap: "0.35rem", fontFamily: "var(--mono-display)", fontSize: "0.65rem", color: networkStatus === "connected" ? "var(--course-green-dark, #14743c)" : "var(--amber, #e8a33d)" })}><span className={css({ h: "0.45rem", w: "0.45rem", borderRadius: "50%", bg: "currentColor" })} />{networkStatus}</span></div>
				<div className={css({ mt: "0.75rem", display: "grid", gap: "0.5rem" })}>{course.members.map((member) => <div key={member.accountId} className={css({ display: "flex", alignItems: "center", gap: "0.55rem", fontSize: "0.78rem" })}><span className={css({ position: "relative", display: "grid", h: "1.75rem", w: "1.75rem", placeItems: "center", borderRadius: "50%", bg: member.role === "teacher" || member.role === "owner" ? "var(--course-green)" : "var(--peer-blue, #3468b3)", fontWeight: 800, color: "white" })}>{member.displayName.charAt(0).toUpperCase()}<span className={css({ position: "absolute", right: "-1px", bottom: "-1px", h: "0.5rem", w: "0.5rem", border: "1px solid var(--paper-deep)", borderRadius: "50%", bg: online.has(member.accountId) ? "var(--phosphor, #4be388)" : "#9ba19a" })} /></span><span className={css({ minW: 0, flex: 1 })}><strong className={css({ display: "block", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>{memberName(member, viewer.accountId)}</strong><span className={css({ fontSize: "0.67rem", color: "var(--ink-soft)", textTransform: "uppercase" })}>{member.role}</span></span>{snapshot.permissions.canRequestTeacherAccess && member.role !== "owner" && member.role !== "teacher" && member.teacherAccess === "private" && <button type="button" onClick={() => void mutate({ id: newCourseOperationId(), courseId, baseRevision: course.revision, type: "teacher-access.request", memberAccountId: member.accountId }, "access")} className={css({ fontSize: "0.65rem", textDecoration: "underline" })}>request access</button>}</div>)}</div>
				<section className={css({ mt: "1.25rem", borderTop: "1px solid var(--ink)", pt: "1rem" })}><p className={s.sectionLabel}>Progress</p><div className={css({ mt: "0.6rem", h: "0.5rem", overflow: "hidden", border: "1px solid var(--ink)", bg: "var(--paper)" })}><div style={{ width: `${courseComple…4404 tokens truncated…pshot.course.revision, type: "card.upsert", card: { id: `card_${crypto.randomUUID().replaceAll("-", "")}`, front: props.cardFront, back: props.cardBack, tags: [], lessonId: activeLesson.id } }, "card").then(props.onCardSaved)}><Plus size={13} /> Add card</button></div></details>}</section>;
}
		case "review.started":
			return action.deckIds.length > 0 ? { ...state, review: { deckIds: [...action.deckIds], index: 0 } } : state;
		case "review.advanced": {
			const index = state.review.index + 1;
			return index < state.review.deckIds.length
				? { ...state, review: { ...state.review, index } }
				: { ...state, review: { deckIds: [], index: 0 } };
		}
		case "review.ended":
			return { ...state, review: { deckIds: [], index: 0 } };
	}
}

export function ComingUp() {
	useSeo({ title: "Coming Up — Keating", description: "Plan spaced-repetition reviews and set your learning priorities.", canonical: "https://keating.help/coming-up" });
	const navigate = useNavigate();
	const [pageState, dispatch] = useReducer(comingUpPageReducer, initialComingUpPageState);
	const { decks, verifications, learnerState } = pageState.data;
	const { status, error } = pageState.feedback;
	const { itemId: draggedId, lane: dropLane } = pageState.drag;
	const { deckIds: reviewDeckIds, index: reviewIndex } = pageState.review;
	const loading = pageState.loadState === "loading";
	const busy = pageState.transferBusy;
	const [mobileLane, setMobileLane] = useState<StudyPriority>("focus");
	const [now, setNow] = useState(() => Date.now());
	const importRef = useRef<HTMLInputElement>(null);

	const loadData = useCallback(async () => {
		await getInitPromise();
		const [nextDecks, nextVerifications, nextLearnerState] = await Promise.all([
			keatingStorage.getDecks(),
			keatingStorage.getVerifications(),
			keatingStorage.getLearnerState(),
		]);
		dispatch({ type: "data.loaded", decks: nextDecks, verifications: nextVerifications, learnerState: nextLearnerState });
	}, []);

	useEffect(() => {
		void loadData().catch((cause) => {
			dispatch({ type: "data.failed", error: cause instanceof Error ? cause.message : String(cause) });
		});
	}, [loadData]);

	useEffect(() => {
		const refreshClock = () => setNow(Date.now());
		const timer = window.setInterval(refreshClock, 60_000);
		window.addEventListener("focus", refreshClock);
		return () => {
			window.clearInterval(timer);
			window.removeEventListener("focus", refreshClock);
		};
	}, []);

	const queue = useMemo(() => learnerState ? buildComingUpQueue({ decks, verifications, learnerState, now }) : emptyQueue(), [decks, learnerState, now, verifications]);
	const currentReviewDeck = reviewDeckIds.length > 0 ? decks.find((deck) => deck.id === reviewDeckIds[reviewIndex]) ?? null : null;
	const dueCardIds = currentReviewDeck?.cards.filter((card) => card.srs.dueAt <= now).map((card) => card.id) ?? [];

	const moveItem = useCallback(async (item: ComingUpItem, priority: StudyPriority) => {
		if (item.priority === priority && item.prioritySource === "learner") return;
		dispatch({ type: "feedback.status", status: `Moving ${item.title} to ${PRIORITIES.find((entry) => entry.id === priority)?.label}.` });
		try {
			const updated = await keatingStorage.setStudyPriority({ targetId: item.targetId, targetType: item.targetType, priority });
			dispatch({ type: "data.loaded", decks, verifications, learnerState: updated });
			setMobileLane(priority);
			dispatch({ type: "feedback.status", status: `${item.title} is now ${PRIORITIES.find((entry) => entry.id === priority)?.label.toLowerCase()}. Review dates were not changed.` });
		} catch (cause) {
			dispatch({ type: "feedback.error", error: cause instanceof Error ? cause.message : String(cause) });
		}
	}, [decks, verifications]);

	const startReview = useCallback((deckIds: string[] = queue.dueDeckIds) => {
		if (deckIds.length === 0) return;
		dispatch({ type: "review.started", deckIds });
		requestAnimationFrame(() => document.getElementById("coming-up-review")?.scrollIntoView({ behavior: "smooth", block: "start" }));
	}, [queue.dueDeckIds]);

	const handleReviewComplete = useCallback(() => {
		if (reviewIndex + 1 < reviewDeckIds.length) {
			dispatch({ type: "review.advanced" });
			return;
		}
		dispatch({ type: "review.ended" });
		dispatch({ type: "feedback.status", status: "Review session complete. Keating scheduled the next appearances from your ratings." });
		void loadData().catch((cause) => {
			dispatch({ type: "data.failed", error: cause instanceof Error ? cause.message : String(cause) });
		});
	}, [loadData, reviewDeckIds.length, reviewIndex]);

	const handleImport = useCallback(async (file: File) => {
		dispatch({ type: "transfer.started" });
		try {
			const lower = file.name.toLowerCase();
			const imported = lower.endsWith(".apkg")
				? await parseAnkiPackage(new Uint8Array(await file.arrayBuffer()))
				: parseAnkiText(await file.text(), file.name);
			let added = 0;
			let updated = 0;
			let unchanged = 0;
			for (const incoming of imported.decks) {
				const existing = await keatingStorage.getDeck(incoming.id);
				const merged = mergeAnkiDeck(existing, incoming);
				await keatingStorage.saveDeck(merged.deck);
				added += merged.added;
				updated += merged.updated;
				unchanged += merged.unchanged;
			}
			await loadData();
			dispatch({ type: "feedback.status", status: `Imported ${formatNumber(imported.cardCount)} cards across ${formatNumber(imported.decks.length)} decks · ${formatNumber(added)} added · ${formatNumber(updated)} updated · ${formatNumber(unchanged)} kept${imported.warnings.length ? ` · ${imported.warnings.join(" ")}` : ""}` });
		} catch (cause) {
			dispatch({ type: "feedback.error", error: cause instanceof Error ? cause.message : String(cause) });
		} finally {
			dispatch({ type: "transfer.finished" });
		}
	}, [loadData]);

	const exportApkg = useCallback(async () => {
		dispatch({ type: "transfer.started" });
		try {
			const bytes = await buildAnkiPackage(decks);
			downloadFile("keating-review-decks.apkg", bytes, "application/octet-stream");
			dispatch({ type: "feedback.status", status: `Exported ${formatNumber(decks.reduce((sum, deck) => sum + deck.cards.length, 0))} cards as a native Anki package.` });
		} catch (cause) {
			dispatch({ type: "feedback.error", error: cause instanceof Error ? cause.message : String(cause) });
		} finally {
			dispatch({ type: "transfer.finished" });
		}
	}, [decks]);

	const exportTsv = useCallback(() => {
		try {
			downloadTextFile("keating-review-decks.tsv", buildAnkiTsv(decks), "text/tab-separated-values;charset=utf-8");
			dispatch({ type: "feedback.status", status: "Exported a tab-separated text fallback for Anki or spreadsheets." });
		} catch (cause) {
			dispatch({ type: "feedback.error", error: cause instanceof Error ? cause.message : String(cause) });
		}
	}, [decks]);

	const completeVerification = useCallback(async (item: ComingUpItem) => {
		dispatch({ type: "feedback.clear" });
		try {
			await keatingStorage.setVerificationCompleted(item.targetId, true);
			dispatch({ type: "feedback.status", status: `${item.title} marked complete.` });
			await loadData();
		} catch (cause) {
			dispatch({ type: "feedback.error", error: cause instanceof Error ? cause.message : String(cause) });
		}
	}, [loadData]);

	if (loading) {
		return <div className={cx("retro-layout", "retro-page", styles.page)}><Nav /><div className={styles.loading}><RefreshCw size={16} />Loading your review queue…</div></div>;
	}

	return (
		<div className={cx("retro-layout", "retro-page", styles.page)}>
			<Nav />
			<LearningInsightsHeader
				current="coming-up"
				context="Learning intelligence // Review runway"
				title="Coming up"
				description="Set what deserves attention, work the reviews that are actually due, and carry decks between Keating and Anki."
			/>
			<main className={styles.main}>
				<div className={styles.metrics}>
					<LearningMetric icon={<Brain size={18} />} label="Cards due now" value={formatNumber(queue.dueCardCount)} detail={queue.overdueCardCount > 0 ? `${formatNumber(queue.overdueCardCount)} overdue by more than a day` : "Nothing overdue by more than a day"} />
					<LearningMetric icon={<Clock3 size={18} />} label="Review time" value={`~${formatNumber(queue.estimatedMinutes)} min`} detail="Estimated from the due cards, not the whole board" />
					<LearningMetric icon={<Layers3 size={18} />} label="Learning items" value={formatNumber(queue.items.length)} detail={`${formatNumber(decks.length)} decks · ${formatNumber(verifications.filter((item) => !item.completed).length)} open checks`} />
				</div>

				<section className={styles.reviewStrip} aria-labelledby="due-review-title">
					<div>
						<h2 id="due-review-title" className={styles.stripTitle}><CheckCircle2 size={18} />{queue.dueCardCount > 0 ? `${formatNumber(queue.dueCardCount)} cards are ready` : "Review runway is clear"}</h2>
						<p className={styles.stripCopy}>{queue.dueCardCount > 0 ? "Priority chooses the order; recall evidence chooses what is due." : "You can still reorganize priorities or import another deck below."}</p>
					</div>
					<button type="button" className={cx(styles.button, styles.accentButton)} disabled={queue.dueCardCount === 0} onClick={() => startReview()}><Play size={15} />Start due review</button>
				</section>

				{currentReviewDeck ? (
					<section id="coming-up-review" className={styles.reviewer} aria-labelledby="review-title">
						<div className={styles.reviewerHead}>
							<div><h2 id="review-title" className={styles.reviewerTitle}>Reviewing {currentReviewDeck.title}</h2><p className={styles.stripCopy}>Deck {reviewIndex + 1} of {reviewDeckIds.length} · {dueCardIds.length} due</p></div>
							<button type="button" className={cx(styles.button, styles.quietButton)} onClick={() => dispatch({ type: "review.ended" })}>End review</button>
						</div>
						<FlashcardRenderer key={currentReviewDeck.id} deck={currentReviewDeck} restrictToCardIds={dueCardIds} autoFocusKeyboard onComplete={handleReviewComplete} />
					</section>
				) : null}

				<section className={styles.workspace} aria-labelledby="priority-board-title">
					<div className={styles.workspaceHead}>
						<div><h2 id="priority-board-title" className={styles.workspaceTitle}>Priority board</h2><p className={styles.workspaceCopy}>Drag cards between lanes or use each card’s priority menu. Moving a card changes your intent—not its spaced-repetition date.</p></div>
						<div className={styles.toolbar}>
							<label className={cx(styles.button, styles.primaryButton)}>
								<Upload size={15} />{busy ? "Working…" : "Import Anki"}
								<input ref={importRef} className={styles.fileInput} type="file" accept=".apkg,.csv,.tsv,.txt,application/octet-stream,text/csv,text/tab-separated-values" disabled={busy} onChange={(event) => { const file = event.target.files?.[0]; if (file) void handleImport(file); event.currentTarget.value = ""; }} />
							</label>
							<button type="button" className={cx(styles.button, styles.quietButton)} disabled={busy || decks.length === 0} onClick={() => void exportApkg()}><Download size={15} />Export .apkg</button>
							<button type="button" className={cx(styles.button, styles.quietButton)} disabled={busy || decks.length === 0} onClick={exportTsv}>TSV fallback</button>
						</div>
					</div>
					<div className={styles.mobileTabs} aria-label="Priority lane">
						{PRIORITIES.map((priority) => {
							const active = mobileLane === priority.id;
							return (
								<button
									key={priority.id}
									type="button"
									data-active={active}
									className={styles.mobileTab}
									style={{ padding: "0.25rem", fontSize: "0.6875rem", lineHeight: "1rem", background: active ? "var(--ink)" : "var(--paper)", color: active ? "var(--paper)" : "var(--ink)" }}
									onClick={() => setMobileLane(priority.id)}
								>
									{priority.id === "low" ? "Low" : priority.label} ({queue.lanes[priority.id].length})
								</button>
							);
						})}
					</div>
					<div className={styles.board}>
						{PRIORITIES.map((priority) => (
							<section
								key={priority.id}
								aria-labelledby={`lane-${priority.id}`}
								className={cx(styles.lane, dropLane === priority.id ? styles.laneDragging : "", css({ display: { base: mobileLane === priority.id ? "block" : "none", md: "block" } }))}
								onDragOver={(event) => { event.preventDefault(); event.dataTransfer.dropEffect = "move"; dispatch({ type: "drag.entered", lane: priority.id }); }}
								onDragLeave={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node)) dispatch({ type: "drag.ended" }); }}
								onDrop={(event) => { event.preventDefault(); const item = queue.items.find((candidate) => candidate.id === (draggedId ?? event.dataTransfer.getData("text/plain"))); dispatch({ type: "drag.ended" }); if (item) void moveItem(item, priority.id); }}
							>
								<div className={styles.laneHead}><div><h3 id={`lane-${priority.id}`} className={styles.laneTitle}>{priority.label}</h3><p className={styles.laneNote}>{priority.note}</p></div><span className={styles.count}>{queue.lanes[priority.id].length}</span></div>
								<div className={styles.laneBody}>
									{queue.lanes[priority.id].length === 0 ? <div className={styles.emptyLane}>{priority.id === "focus" ? "Drop the work that deserves your attention here." : "Nothing here yet."}</div> : queue.lanes[priority.id].map((item) => (
										<QueueCard
											key={item.id}
											item={item}
											now={now}
											dragging={draggedId === item.id}
											onDragStart={() => dispatch({ type: "drag.started", itemId: item.id })}
											onDragEnd={() => dispatch({ type: "drag.ended" })}
											onPriority={(nextPriority) => void moveItem(item, nextPriority)}
											onReview={() => startReview([item.targetId])}
											onCompleteCheck={() => void completeVerification(item)}
											onOpenTopic={() => navigate({ to: "/chat" })}
										/>
									))}
								</div>
							</section>
						))}
					</div>
					{status || error ? <div className={cx(styles.status, error ? styles.statusError : "")} role="status" aria-live="polite">{error || status}</div> : null}
				</section>
				<p className={css({ mt: "1rem", display: "flex", alignItems: "center", gap: "0.4rem", fontSize: "0.6875rem", color: "var(--ink-soft)" })}><ArrowRight size={13} />Anki imports run locally in this browser. Templates never execute, and media is left out of Keating’s text-first reviews.</p>
			</main>
		</div>
	);
}
import type {
	FlashcardDeck,
	LearnerState,
	StudyPriority,
	StudyPriorityRecord,
	StudyPriorityTarget,
	Verification,
} from "./storage";

const MS_PER_DAY = 86_400_000;

export interface ComingUpItem {
	id: string;
	targetId: string;
	targetType: StudyPriorityTarget;
	priority: StudyPriority;
	prioritySource: "learner" | "recommended";
	title: string;
	topic: string;
	description: string;
	dueCount: number;
	overdueCount: number;
	nextDueAt: number | null;
	estimatedMinutes: number;
	weakConcepts: string[];
	cardCount: number;
	createdAt: number;
}

export interface ComingUpQueue {
	items: ComingUpItem[];
	lanes: Record<StudyPriority, ComingUpItem[]>;
	dueCardCount: number;
	overdueCardCount: number;
	estimatedMinutes: number;
	dueDeckIds: string[];
}

export interface ComingUpSources {
	decks: FlashcardDeck[];
	verifications: Verification[];
	learnerState: LearnerState;
	now?: number;
}

function priorityFor(
	targetType: StudyPriorityTarget,
	targetId: string,
	recommended: StudyPriority,
	priorities: Map<string, StudyPriorityRecord>,
): Pick<ComingUpItem, "priority" | "prioritySource"> {
	const saved = priorities.get(`${targetType}:${targetId}`);
	return saved
		? { priority: saved.priority, prioritySource: "learner" }
		: { priority: recommended, prioritySource: "recommended" };
}

function compareUrgency(left: ComingUpItem, right: ComingUpItem): number {
	if (left.overdueCount !== right.overdueCount) return right.overdueCount - left.overdueCount;
	if (left.dueCount !== right.dueCount) return right.dueCount - left.dueCount;
	const leftDue = left.nextDueAt ?? Number.POSITIVE_INFINITY;
	const rightDue = right.nextDueAt ?? Number.POSITIVE_INFINITY;
	if (leftDue !== rightDue) return leftDue - rightDue;
	return left.title.localeCompare(right.title);
}

export function buildComingUpQueue({ decks, verifications, learnerState, now = Date.now() }: ComingUpSources): ComingUpQueue {
	const priorities = new Map(learnerState.studyPriorities.map((record) => [
		`${record.targetType}:${record.targetId}`,
		record,
	]));
	const topicProfiles = new Map(learnerState.topicProfiles.map((profile) => [profile.topic, profile]));
	const items: ComingUpItem[] = [];

	for (const deck of decks) {
		const dueCards = deck.cards.filter((card) => card.srs.dueAt <= now);
		const overdueCards = dueCards.filter((card) => card.srs.dueAt < now - MS_PER_DAY);
		const nextDueAt = deck.cards.length > 0
			? Math.min(...deck.cards.map((card) => card.srs.dueAt))
			: null;
		const profile = topicProfiles.get(deck.topic);
		items.push({
			id: `deck:${deck.id}`,
			targetId: deck.id,
			targetType: "deck",
			...priorityFor("deck", deck.id, dueCards.length > 0 ? "focus" : "maintain", priorities),
			title: deck.title,
			topic: deck.topic,
			description: deck.description?.trim() || "Spaced-repetition deck",
			dueCount: dueCards.length,
			overdueCount: overdueCards.length,
			nextDueAt,
			estimatedMinutes: Math.max(1, Math.ceil(dueCards.length * 1.25)),
			weakConcepts: profile?.reportedChallenges ?? [],
			cardCount: deck.cards.length,
			createdAt: deck.createdAt,
		});
	}

	for (const verification of verifications.filter((item) => !item.completed)) {
		const ageDays = Math.max(0, (now - verification.createdAt) / MS_PER_DAY);
		items.push({
			id: `verification:${verification.id}`,
			targetId: verification.id,
			targetType: "verification",
			...priorityFor("verification", verification.id, ageDays >= 7 ? "focus" : "maintain", priorities),
			title: `${verification.topic} check`,
			topic: verification.topic,
			description: verification.checklist.trim().split("\n").find(Boolean)?.replace(/^[-*\d.)\s]+/, "") || "Open knowledge check",
			dueCount: 0,
			overdueCount: 0,
			nextDueAt: null,
			estimatedMinutes: 5,
			weakConcepts: topicProfiles.get(verification.topic)?.reportedChallenges ?? [],
			cardCount: 0,
			createdAt: verification.createdAt,
		});
	}

	for (const profile of learnerState.topicProfiles.filter((item) => item.status === "needs-review")) {
		const hasTopicWork = items.some((item) => item.topic === profile.topic);
		if (hasTopicWork) continue;
		items.push({
			id: `topic:${profile.topic}`,
			targetId: profile.topic,
			targetType: "topic",
			...priorityFor("topic", profile.topic, "focus", priorities),
			title: profile.topic,
			topic: profile.topic,
			description: "Needs a fresh retrieval check",
			dueCount: 0,
			overdueCount: 0,
			nextDueAt: null,
			estimatedMinutes: 8,
			weakConcepts: profile.reportedChallenges,
			cardCount: 0,
			createdAt: profile.lastEvidenceAt,
		});
	}

	const sorted = [...items].sort(compareUrgency);
	const lanes: ComingUpQueue["lanes"] = { focus: [], maintain: [], low: [] };
	for (const item of sorted) lanes[item.priority].push(item);
	const dueDeckIds = sorted
		.filter((item) => item.targetType === "deck" && item.dueCount > 0)
		.sort((left, right) => {
			const priorityRank: Record<StudyPriority, number> = { focus: 0, maintain: 1, low: 2 };
			return priorityRank[left.priority] - priorityRank[right.priority] || compareUrgency(left, right);
		})
		.map((item) => item.targetId);

	return {
		items: sorted,
		lanes,
		dueCardCount: sorted.reduce((sum, item) => sum + item.dueCount, 0),
		overdueCardCount: sorted.reduce((sum, item) => sum + item.overdueCount, 0),
		estimatedMinutes: sorted.reduce((sum, item) => sum + (item.dueCount > 0 ? item.estimatedMinutes : 0), 0),
		dueDeckIds,
	};
}

