	const messages: AgentMessage[] = [];
	let timestamp = Date.now();
	for (const turn of turns) {
		if (turn.user.trim()) {
			messages.push({
				role: "user",
				content: [{ type: "text", text: turn.user.trim() }],
				timestamp: timestamp++,
			} as AgentMessage);
